			require_log_acl_guard.mainLog.info("[MainBootstrap] Skill disable-to-model-invocation migration kicked");
			require_log_acl_guard.kickSkillModelInvocationToOverrideMigration({
				userSkillsDir,
				configDir,
				logger: require_log_acl_guard.mainLog
			});
			require_log_acl_guard.mainLog.info("[MainBootstrap] Skill model-invocation-to-override migration kicked");
			ctx.setCapability(BOOT_AUTH, auth);
			ctx.setCapability(BOOT_SIDECAR, sidecar);
