		backgroundPromise.catch((err) => {
			require_log_acl_guard.mainLog.error("[MainBootstrap] Background services start error:", err);
		});
		markStartup("B14");
		require_log_acl_guard.mainLog.info("[MainBootstrap] Bootstrap complete, returning handle");
		markStartup("B15");
