/**
* 仅 evalMode 下启动 Eval Proxy Server。
*
* 该模块通过动态 import 加载：当 __EVAL_MODE_ENABLED__ 在构建期被折叠为 false
* （即 WORKBUDDY_EVAL_MODE=1 未在构建时设置），打包器可完全排除本模块，不进生产制品。
* 构建期开关是"是否启用 eval proxy"的单一真相源，无需额外运行时判断。
*
* host 支持 WORKBUDDY_EVAL_HOST 覆盖；仅当该 env 变量存在时才显式传 host，让 server 侧
* 保留自己的安全默认（loopback）。
*/
async function startEvalProxyServer(deps) {
	const { evalModeEnabled, daemon } = deps;
	if (!evalModeEnabled) return;
	const { EvalProxyServer } = await Promise.resolve().then(() => require("./eval-inject-server.js"));
	const evalHost = process.env.WORKBUDDY_EVAL_HOST;
	const server = new EvalProxyServer(require_log_acl_guard.mainLog, {
		daemon,
		...evalHost ? { host: evalHost } : {}
	});
	await server.start();
	server.markAppReady();
	server.markMainBootstrapReady();
	require_log_acl_guard.mainLog.info(`[MainBootstrap] Eval proxy ready at ${server.getUrl()}`);
	return server;
}
