//#region src/main/recovery/gpu-crash-watch-controller.ts
/**
* GpuCrashWatchController GPU crash 观察采样链执行器。
* 每个 WindowManager 持有一个实例，转发 GPU crash / renderer-gone / quit 三个入口。
*/
var GpuCrashWatchController = class {
	deps;
	watchTimer = null;
	active = false;
	epoch = 0;
	probeCount = 0;
	consecutiveUnresponsive = 0;
	crashCountInWatch = 0;
	constructor(deps) {
		this.deps = deps;
	}
	/** 观察是否在途（供 render-process-gone 路径判断是否属于 GPU crash 级联）。 */
	get isActive() {
		return this.active;
	}
	/**
	* 启动观察采样链。若已在途，则第 2 次以上 GPU crash 直接升级重建（关注点 2）。
	* @param delayMs 首轮采样前的延迟（由 policy 的 watch 决策给出）。
	*/
	start(reason, delayMs) {
		if (this.active) {
			this.crashCountInWatch += 1;
			this.deps.logger.warn(`[GpuCrashWatch] GPU crash again within watch window (count=${this.crashCountInWatch}), escalate to rebuild`);
			this.deps.onCascadeDetected(reason, "gpu-crash-repeated-in-watch");
			return;
		}
		const { watchMaxProbes } = this.deps.policy.watchConfig;
		const epoch = ++this.epoch;
		this.active = true;
		this.crashCountInWatch = 1;
		this.probeCount = 0;
		this.consecutiveUnresponsive = 0;
		this.deps.logger.info(`[GpuCrashWatch] GPU crash, renderer still functional, watch for cascade (interval=${delayMs}ms, maxProbes=${watchMaxProbes})`);
		this.watchTimer = setTimeout(() => this.runProbe(reason, epoch), delayMs);
	}
	/** 停止观察采样链并重置状态（递增 epoch 作废在途的迟到探针回调）。 */
	stop() {
		if (this.watchTimer !== null) {
			clearTimeout(this.watchTimer);
			this.watchTimer = null;
		}
		this.active = false;
		this.epoch += 1;
		this.probeCount = 0;
		this.consecutiveUnresponsive = 0;
		this.crashCountInWatch = 0;
	}
	/**
	* 观察窗口内单次采样（串行链的一环）：探测窗口硬状态 + 一次带超时的响应性探针，
	* 探针 settle 后交由 policy 决策。串行保证「一轮采样 = 一次记账」，无重叠双计。
	*/
	runProbe(reason, epoch) {
		if (epoch !== this.epoch || !this.active) return;
		this.watchTimer = null;
		if (this.deps.isQuitting()) {
			this.stop();
			return;
		}
		if (this.deps.isWindowUnusable()) {
			this.finishProbe(reason, epoch, {
				unresponsive: false,
				hardUnusable: true
			});
			return;
		}
		this.deps.probeRenderer().then((responsive) => {
			this.finishProbe(reason, epoch, {
				unresponsive: !responsive,
				hardUnusable: false
			});
		}).catch(() => {
			this.finishProbe(reason, epoch, {
				unresponsive: true,
				hardUnusable: false
			});
		});
	}
	/**
	* 汇总单次采样结果，更新计数并交由 policy 决策后续动作：继续观察则排下一轮，
	* 命中不可用则重建，达上限仍健康则放行。
	*/
	finishProbe(reason, epoch, result) {
		if (epoch !== this.epoch) return;
		this.probeCount += 1;
		this.consecutiveUnresponsive = result.unresponsive ? this.consecutiveUnresponsive + 1 : 0;
		const decision = this.deps.policy.decideOnProbe({
			windowUnusable: result.hardUnusable,
			probeUnresponsive: result.unresponsive,
			consecutiveUnresponsive: this.consecutiveUnresponsive,
			probeCount: this.probeCount
		});
		if (decision.action === "continue") {
			const { watchIntervalMs } = this.deps.policy.watchConfig;
			this.watchTimer = setTimeout(() => this.runProbe(reason, epoch), watchIntervalMs);
			return;
		}
		const probes = this.probeCount;
		const consecutiveUnresponsive = this.consecutiveUnresponsive;
		this.stop();
		if (decision.action === "release") {
			this.deps.logger.info(`[GpuCrashWatch] window healthy after ${probes} probes, no rebuild`);
			return;
		}
		this.deps.logger.warn(`[GpuCrashWatch] cascade detected (${decision.reasonTag}, probes=${probes}, consecutiveUnresponsive=${consecutiveUnresponsive}), rebuilding`);
		this.deps.onCascadeDetected(reason, decision.reasonTag);
	}
};
//#endregion
//#region src/main/recovery/gpu-recovery-policy.ts
var DEFAULT_GPU_RECOVERY_CONFIG = {
	rebuildDelayMs: 1e3,
	watchIntervalMs: 15e3,
	watchMaxProbes: 40,
	unresponsiveProbeThreshold: 3,
	probeTimeoutMs: 5e3
};
/**
* GPU 恢复决策器（无状态纯函数封装）。每次 GPU crash 事件调用 `decide(event)`，
* 由 WindowManager 执行返回的副作用。
*/
var GpuRecoveryPolicy = class {
	config;
	constructor(config = DEFAULT_GPU_RECOVERY_CONFIG) {
		this.config = config;
	}
	/** 观察参数（供 WindowManager 驱动周期采样循环）。 */
	get watchConfig() {
		return this.config;
	}
	decide(event) {
		if (event.rebuildPending) return {
			action: "noop",
			reasonTag: "rebuild-already-pending",
			delayMs: 0
		};
		if (!event.windowUnusable) return {
			action: "watch",
			reasonTag: "window-still-functional-watch",
			delayMs: this.config.watchIntervalMs
		};
		return {
			action: "rebuild",
			reasonTag: `gpu-crash-${event.reason || "unknown"}`,
			delayMs: this.config.rebuildDelayMs
		};
	}
	/**
	* 观察窗口内单次采样后的纯决策（issue #85185 核心）。
	*
	* 相比首版「30s 后单次终点检查 destroyed/crashed」，此处支持两类不可用信号：
	* - 硬不可用（windowUnusable）：窗口/webContents 已 destroyed 或 isCrashed，立即重建。
	* - 软不可用（卡死）：进程还活着但连续 unresponsiveProbeThreshold 次探针无响应，
	*   对应现网「白屏 + IPC 全超时但 webContents 未 crash」的中间态，升级重建。
	* 两者都未命中且未达 watchMaxProbes → 继续观察。
	*
	* 达上限（watchMaxProbes）时 watchMaxProbes 是硬上限，观察链必须终结（release 或 rebuild），
	* 不再无限延长——否则 renderer 每几轮偶尔回一次成功（consecutiveUnresponsive 被清零、
	* 达不到升级阈值）就能把观察链无限拖住，持续持有闭包 / executeJavaScript 待响应队列，
	* 用户白屏时长也远超预期：
	* - 本次探针有响应 → 放行（window-recovered），窗口确已恢复。
	* - 本次探针仍无响应 → 升级重建（gpu-crash-cascade-tail-unresponsive）。这属于 issue #85185
	*   要覆盖的长尾中间态尾部：跑满整个观察窗口仍零星卡死，视同级联不可用而非误判恢复。
	*/
	decideOnProbe(event) {
		if (event.windowUnusable) return {
			action: "rebuild",
			reasonTag: "gpu-crash-cascade-detected",
			delayMs: 0
		};
		if (event.consecutiveUnresponsive >= this.config.unresponsiveProbeThreshold) return {
			action: "rebuild",
			reasonTag: "gpu-crash-cascade-unresponsive",
			delayMs: 0
		};
		if (event.probeCount >= this.config.watchMaxProbes) return event.probeUnresponsive ? {
			action: "rebuild",
			reasonTag: "gpu-crash-cascade-tail-unresponsive",
			delayMs: 0
		} : {
			action: "release",
			reasonTag: "window-recovered",
			delayMs: 0
		};
		return {
			action: "continue",
			reasonTag: "still-watching",
			delayMs: 0
		};
	}
};
//#endregion
//#region src/main/recovery/renderer-recovery-policy.ts
var DEFAULT_RENDERER_RECOVERY_CONFIG = {
	consecutiveWindowMs: 6e4,
	thresholdConsecutive: 2,
	thresholdGiveUp: 5,
	normalDelayMs: 3e3,
	oomDelayMs: 5e3,
	rendererStabilityMs: 3e4,
	totalOomThreshold: 10
};
/**
* 状态机：维护短时窗口内的崩溃历史，给出恢复决策。
*
* 使用约定：每次 `render-process-gone` 触发时调用 `decide(event)`，
* 拿到 RendererRecoveryDecision 后由 WindowManager 执行实际副作用。
*
* 不持久化：进程重启后历史清空（这是合理的，issue #56760 看到的"一个用户 17s 崩 5 次"
* 是同一进程生命周期内的 reload 抖动，不会跨进程）。
*/
var RendererRecoveryPolicy = class {
	config;
	history = [];
	gaveUp = false;
	/**
	* 最近一次 onRecoverySucceeded 调用时间戳（ms）。null 表示从未成功恢复或
	* 上次时间戳已被 decide 消费。配合 rendererStabilityMs 区分"加载完成后
	* 短期又崩"（恢复未真正完成）和"使用一段时间后又崩"（孤立新崩溃）。
	*/
	lastRecoverySucceededAt = null;
	/**
	* 进程生命周期内累计 OOM 次数（不受 consecutiveWindowMs trim 影响，也不被
	* onRecoverySucceeded 清零）。达到 config.totalOomThreshold 后升级到 give-up。
	* 只在进程重启时归零，与"多次 OOM 后建议用户重启"的产品语义对齐。
	* 详见 config.totalOomThreshold 的 JSDoc。
	*/
	totalOomCount = 0;
	constructor(config = DEFAULT_RENDERER_RECOVERY_CONFIG) {
		this.config = config;
	}
	/**
	* 当前窗口内的崩溃次数（含 OOM）。仅用于测试 / 诊断。
	*/
	get recentCrashCount() {
		return this.history.length;
	}
	/**
	* 进程生命周期内累计 OOM 次数。仅用于测试 / 诊断。
	*/
	get recentOomCount() {
		return this.totalOomCount;
	}
	/**
	* 重置崩溃历史（reload 成功后调用，避免老的崩溃事件污染后续判断）。
	* 同时记录时间戳到 lastRecoverySucceededAt；下次 decide() 时若仍在
	* rendererStabilityMs 窗口内，将走 clear-cache-and-reload 而非 reload。
	* Patch 修复 issue #56760 B 类场景。
	* @param timestamp 可选注入的时间戳（ms），默认 Date.now()。单测场景
	*   使用固定 T0 模拟时间，避免与 decide() 传入的 timestamp 错位。
	*/
	onRecoverySucceeded(timestamp = Date.now()) {
		this.history = [];
		this.gaveUp = false;
		this.lastRecoverySucceededAt = timestamp;
	}
	decide(event) {
		const cutoff = event.timestamp - this.config.consecutiveWindowMs;
		this.history = this.history.filter((e) => e.timestamp >= cutoff);
		if (this.gaveUp) return {
			action: "give-up",
			reasonTag: "already-gave-up",
			delayMs: 0
		};
		if (!(event.reason === "crashed" || event.reason === "oom" || event.reason === "killed" || event.reason === "abnormal-exit" || event.reason === "launch-failed" || event.reason === "integrity-failure" || event.reason === "clean-exit" && event.exitCode !== 0)) return {
			action: "none",
			reasonTag: `clean-exit-code-${event.exitCode}`,
			delayMs: 0
		};
		let inStabilityWindow = false;
		if (this.lastRecoverySucceededAt !== null) {
			const sinceRecovery = event.timestamp - this.lastRecoverySucceededAt;
			if (sinceRecovery >= 0 && sinceRecovery < this.config.rendererStabilityMs) inStabilityWindow = true;
			this.lastRecoverySucceededAt = null;
		}
		this.history.push(event);
		if (event.reason === "oom") this.totalOomCount += 1;
		if (this.history.length >= this.config.thresholdGiveUp) {
			this.gaveUp = true;
			return {
				action: "give-up",
				reasonTag: `consecutive-crashes-${this.history.length}`,
				delayMs: 0
			};
		}
		if (this.totalOomCount >= this.config.totalOomThreshold) {
			this.gaveUp = true;
			return {
				action: "give-up",
				reasonTag: `recurring-oom-${this.totalOomCount}`,
				delayMs: 0
			};
		}
		if (event.reason === "oom") return {
			action: "clear-cache-and-reload",
			reasonTag: "oom",
			delayMs: this.config.oomDelayMs
		};
		if (inStabilityWindow) return {
			action: "clear-cache-and-reload",
			reasonTag: "unstable-after-reload",
			delayMs: this.config.oomDelayMs
		};
		if (this.history.length >= this.config.thresholdConsecutive) return {
			action: "clear-cache-and-reload",
			reasonTag: `consecutive-${this.history.length}`,
			delayMs: this.config.oomDelayMs
		};
		return {
			action: "reload",
			reasonTag: event.reason,
			delayMs: this.config.normalDelayMs
		};
	}
};
