//#region src/main/window/select-all-edit-command.ts
/**
* 同时覆盖 Slate 富文本与原生 input/textarea。
* Slate 消费 IPC；普通控件忽略 IPC，继续由 Chromium 原生命令完成全选。
*/
function dispatchSelectAllEditCommand(webContents) {
	if (webContents.isDestroyed()) return;
	webContents.send("wb:edit-command", "selectAll");
	webContents.selectAll();
}
