//#region src/main/window/tray/close-to-tray-hint-store.ts
/**
* Close-to-tray 提示的一次性展示状态存储（userData 持久化）。
*
* 首次窗口关闭到 tray 时，Windows 会通过 Notification / balloon 提示
* 「已最小化到托盘」，避免用户以为程序被关掉。展示过一次后就永久不再展示，
* 状态存到 userData/close-to-tray-hint.json。
*
* 支持 env var WORKBUDDY_RESET_TRAY_HINT=1 一次性清空状态（调试用）；
* WORKBUDDY_ALWAYS_SHOW_TRAY_HINT=1 让 hint 每次都展示（不消费一次性状态）。
*
* 内部持有 cache 避免重复读盘；write 走 tmp + rename 原子替换。
*/
var CLOSE_TO_TRAY_HINT_FILE = "close-to-tray-hint.json";
var CLOSE_TO_TRAY_HINT_STATE_VERSION = 1;
var CloseToTrayHintStore = class {
	shownCache;
	resetApplied = false;
	getHintPath() {
		return path.join(electron.app.getPath("userData"), CLOSE_TO_TRAY_HINT_FILE);
	}
	applyResetIfNeeded() {
		if (this.resetApplied || !isEnabledEnv(process.env.WORKBUDDY_RESET_TRAY_HINT)) return;
		this.resetApplied = true;
		this.shownCache = false;
		try {
			fs.unlinkSync(this.getHintPath());
			require_log_acl_guard.windowLog.info("[Tray] Close-to-tray hint state reset by WORKBUDDY_RESET_TRAY_HINT");
		} catch (err) {
			if (err?.code !== "ENOENT") require_log_acl_guard.windowLog.warn("[Tray] Failed to reset close-to-tray hint state:", err);
		}
	}
	/** 是否已展示过 close-to-tray 提示。首次调用会尝试从磁盘读取并缓存。 */
	hasShown() {
		this.applyResetIfNeeded();
		if (this.shownCache !== void 0) return this.shownCache;
		try {
			const raw = fs.readFileSync(this.getHintPath(), "utf8");
			const state = JSON.parse(raw);
			this.shownCache = state.version === CLOSE_TO_TRAY_HINT_STATE_VERSION && state.shown === true;
		} catch (err) {
			if (err?.code !== "ENOENT") require_log_acl_guard.windowLog.warn("[Tray] Failed to read close-to-tray hint state:", err);
			this.shownCache = false;
		}
		return this.shownCache;
	}
	/** 标记 close-to-tray 提示已展示，同步写盘（tmp + rename 原子替换）。 */
	markShown() {
		this.shownCache = true;
		try {
			const hintPath = this.getHintPath();
			const dir = path.dirname(hintPath);
			if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
			const tmpPath = `${hintPath}.tmp`;
			const state = {
				version: CLOSE_TO_TRAY_HINT_STATE_VERSION,
				shown: true
			};
			fs.writeFileSync(tmpPath, JSON.stringify(state, null, 2), "utf8");
			fs.renameSync(tmpPath, hintPath);
		} catch (err) {
			require_log_acl_guard.windowLog.warn("[Tray] Failed to persist close-to-tray hint state:", err);
		}
	}
};
//#endregion
//#region src/main/window/tray/pick-ico-frame.ts
/**
* 从多分辨率 `.ico` 里挑出与目标像素尺寸匹配的 PNG 帧。
*
* 为什么需要这个模块（而不是把 .ico 直接交给 nativeImage）：
*
* Electron 在 Windows 上读 `.ico` 时按**固定 256** 调 LoadImage，不做 DPI 选帧。
* 实测（Electron 37）：
*   - `nativeImage.createFromPath('icon.ico').getSize()` → 恒为 256x256，
*     `getScaleFactors()` → `[1]`；
*   - 即便构造一个「只含 16px 一帧」的 .ico，读出来仍报 256x256，且边缘能量
*     显著低于真 256 帧 —— 说明那是 16px 帧被放大到 256 的糊图。
*
* 结论：ICO 里的 16/20/24/32/40px 小帧对 Tray 完全不可见，实际链路退化成
* 「256px 位图 → Shell_NotifyIcon 缩到 SM_CXSMICON」，这正是托盘图标发虚的根因
* （#80539）。
*
* 而 ICO 的每一帧本身就是完整 PNG 字节流（见 @genie/cli 的 PngToIcoProcessor，
* 写入的都是 PNG 帧），`nativeImage.createFromBuffer` 认 PNG。于是自己解析目录、
* 取出 DPI 匹配的那一帧直接喂给 Tray，即可零缩放拿到「按该尺寸原生下采样 +
* 已锐化」的像素，比让 Skia/Shell 从 256 缩下来更锐（实测 16px 边缘能量
* 34.90 vs 30.11）。
*
* 只解析、不解码：本模块不依赖任何图像库，纯 Buffer 偏移读取。
*/
/** PNG 文件签名。ICO 帧要么是 PNG，要么是 BMP(DIB)，这里只接受 PNG 帧。 */
var PNG_MAGIC = Buffer.from([
	137,
	80,
	78,
	71,
	13,
	10,
	26,
	10
]);
var ICO_HEADER_SIZE = 6;
var ICO_ENTRY_SIZE = 16;
/** ICO 目录项里宽/高为 0 表示 256（单字节存不下 256）。 */
var ICO_SIZE_256 = 256;
/**
* 列出 `.ico` 中所有 PNG 帧，按边长升序。
*
* 对畸形/非 ICO/纯 BMP 帧的输入返回空数组，由调用方走兜底路径 —— 托盘图标属于
* "宁可退化也不能崩" 的链路（窗口被 hide 到托盘后，没有 tray 用户就找不回窗口，
* 见 #32637）。
*/
function listIcoPngFrames(buffer) {
	if (buffer.length < ICO_HEADER_SIZE) return [];
	if (buffer.readUInt16LE(0) !== 0 || buffer.readUInt16LE(2) !== 1) return [];
	const count = buffer.readUInt16LE(4);
	const frames = [];
	for (let i = 0; i < count; i++) {
		const entryOffset = ICO_HEADER_SIZE + i * ICO_ENTRY_SIZE;
		if (entryOffset + ICO_ENTRY_SIZE > buffer.length) break;
		const size = buffer[entryOffset] || ICO_SIZE_256;
		const dataLength = buffer.readUInt32LE(entryOffset + 8);
		const dataOffset = buffer.readUInt32LE(entryOffset + 12);
		if (dataLength <= 0 || dataOffset + dataLength > buffer.length) continue;
		const png = buffer.subarray(dataOffset, dataOffset + dataLength);
		if (png.length < PNG_MAGIC.length || !png.subarray(0, PNG_MAGIC.length).equals(PNG_MAGIC)) continue;
		frames.push({
			size,
			png
		});
	}
	return frames.sort((a, b) => a.size - b.size);
}
/**
* 选出最适合 `targetSize` 物理像素的 PNG 帧。
*
* 策略：优先取 **>= targetSize 的最小帧**，没有更大的才退回最大帧。
* 宁可下采样也不上采样 —— 放大必然发虚，缩小只损失细节。
* 例如 175% 缩放需要 28px，没有 28px 帧时取 32px（32→28 只是 1.14x 轻微下采），
* 而不是把 24px 拉大。
*
* 找不到任何可用 PNG 帧时返回 undefined。
*/
function pickIcoPngFrame(buffer, targetSize) {
	const frames = listIcoPngFrames(buffer);
	if (frames.length === 0) return;
	return frames.find((frame) => frame.size >= targetSize) ?? frames[frames.length - 1];
}
//#endregion
//#region src/main/window/tray/resolve-tray-icon.ts
/**
* Tray icon 资源路径解析 —— 覆盖 dev / packaged / asar.unpacked 三套布局。
*
* 优先级：`resolveBundledAsset()` 覆盖通用 dev/packaged 场景，兜底扫描
* `process.resourcesPath` 下的 `resources/` / `app.asar.unpacked/**`。
*
* 平台差异：
* - darwin 优先 `trayTemplate.png`（monochrome，配合 setTemplateImage(true)
*   自动适配深/浅色系统主题）
* - win32 优先 `.ico`（nativeImage 原生支持，electron-builder 打包时始终
*   会作为 app icon 落在 buildResources）
* - linux 优先 `tray-linux.png`（24px 彩色，打包期按品牌生成）
* - 其他 fallback：`icon.png`
*
* 同步 fs.existsSync：tray 图标解析在 window 创建链路上同步执行，无 IO
* 热路径压力。
*/
require_code_cache.init_bundled_assets();
/**
* 解析 tray icon 磁盘绝对路径。找不到返回 undefined 并 WARN 记录搜索过的候选。
*/
function resolveTrayIconPath() {
	const isWindows = process.platform === "win32";
	const isDarwin = process.platform === "darwin";
	const isLinux = !isWindows && !isDarwin;
	const candidates = [];
	if (isDarwin) {
		const tplPath = require_code_cache.resolveBundledAsset("trayTemplate.png");
		if (tplPath) candidates.push(tplPath);
	}
	if (isWindows) {
		const icoPath = require_code_cache.resolveBundledAsset("icon.ico");
		if (icoPath) candidates.push(icoPath);
	}
	if (isLinux) {
		const linuxTrayPath = require_code_cache.resolveBundledAsset("tray-linux.png");
		if (linuxTrayPath) candidates.push(linuxTrayPath);
	}
	const pngPath = require_code_cache.resolveBundledAsset("icon.png");
	if (pngPath) candidates.push(pngPath);
	if (typeof process.resourcesPath === "string" && process.resourcesPath.length > 0) {
		const rp = process.resourcesPath;
		const extra = [
			...isDarwin ? [
				path.join(rp, "trayTemplate.png"),
				path.join(rp, "resources", "trayTemplate.png"),
				path.join(rp, "app.asar.unpacked", "resources", "trayTemplate.png"),
				path.join(rp, "app.asar.unpacked", "dist", "resources", "trayTemplate.png")
			] : [],
			...isWindows ? [path.join(rp, "icon.ico")] : [],
			...isLinux ? [
				path.join(rp, "tray-linux.png"),
				path.join(rp, "resources", "tray-linux.png"),
				path.join(rp, "app.asar.unpacked", "resources", "tray-linux.png"),
				path.join(rp, "app.asar.unpacked", "dist", "resources", "tray-linux.png")
			] : [],
			path.join(rp, "icon.png"),
			path.join(rp, "resources", "icon.png"),
			...isWindows ? [path.join(rp, "resources", "icon.ico")] : [],
			path.join(rp, "app.asar.unpacked", "resources", "icon.png"),
			path.join(rp, "app.asar.unpacked", "dist", "resources", "icon.png")
		];
		for (const p of extra) if (!candidates.includes(p)) candidates.push(p);
	}
	const found = candidates.find((p) => {
		try {
			return fs.existsSync(p);
		} catch {
			return false;
		}
	});
	if (!found) require_log_acl_guard.windowLog.warn(`[Tray] Icon asset not found. platform=${process.platform}, __dirname=${__dirname}, resourcesPath=${process.resourcesPath}, searched=${JSON.stringify(candidates)}`);
	else require_log_acl_guard.windowLog.info(`[Tray] Icon resolved: ${found}`);
	return found;
}
//#endregion
//#region src/main/window/tray/tray-menu-builder.ts
var TRAY_SECTION_MAX_VISIBLE = 3;
function buildSessionMenuItem(item, onClick) {
	if (process.platform === "darwin") return {
		label: item.title,
		sublabel: item.typeLabel || void 0,
		click: () => onClick(item.sessionId)
	};
	return {
		label: item.typeLabel ? `${item.title} - ${item.typeLabel}` : item.title,
		click: () => onClick(item.sessionId)
	};
}
function isMacOsHeaderMenuItemSupported() {
	if (process.platform !== "darwin" || typeof process.getSystemVersion !== "function") return false;
	const major = Number.parseInt(process.getSystemVersion().split(".")[0] ?? "", 10);
	return Number.isFinite(major) && major >= 14;
}
function buildSection(title, items, maxVisible, moreLabel, onClick, variant) {
	if (items.length === 0) return [];
	const result = [{ type: "separator" }, variant === "dock" && isMacOsHeaderMenuItemSupported() ? {
		label: title,
		type: "header"
	} : {
		label: title,
		enabled: false
	}];
	const visible = items.slice(0, maxVisible);
	for (const item of visible) result.push(buildSessionMenuItem(item, onClick));
	if (items.length > maxVisible) {
		const submenu = items.slice(maxVisible).map((item) => buildSessionMenuItem(item, onClick));
		result.push({
			label: moreLabel,
			submenu
		});
	}
	return result;
}
function buildTrayMenuTemplate(sections, locale, callbacks, options) {
	const max = 3;
	const moreLabel = require_log_acl_guard.getMenuTranslation("trayMore", locale);
	const showActions = options?.showActions !== false;
	const variant = options?.variant ?? "tray";
	const template = [
		...buildSection(require_log_acl_guard.getMenuTranslation("trayRunning", locale), sections.running, max, moreLabel, callbacks.onSessionClick, variant),
		...buildSection(require_log_acl_guard.getMenuTranslation("trayUnread", locale), sections.unread, max, moreLabel, callbacks.onSessionClick, variant),
		...buildSection(require_log_acl_guard.getMenuTranslation("trayRecent", locale), sections.recent, max, moreLabel, callbacks.onSessionClick, variant)
	];
	if (showActions) template.push({ type: "separator" }, {
		label: require_log_acl_guard.getMenuTranslation("trayNewChat", locale),
		click: () => callbacks.onNewChat()
	}, {
		label: require_log_acl_guard.getMenuTranslation("trayOpenWorkbuddy", locale),
		click: () => callbacks.onShowWindow()
	}, { type: "separator" }, {
		label: require_log_acl_guard.getMenuTranslation("trayQuit", locale),
		click: () => callbacks.onQuit()
	});
	return template;
}
