/**
* open-file 路由器（#67931）。
*
* 承接到达源：
*   1. macOS `app.on('open-file')` —— early-open-file-capture → `handleFromMacosOpenFileEvent`
*   2. Windows argv / second-instance —— caller 分流后调用：
*      - `.zip`（微信聊天记录）→ `handleWechatOnly`
*      - OS 独立窗白名单文件 → `enqueueOfficeOsOpen`
*      - 文件夹 → `enqueueOpenFolder`
*
* ⚠️ 队列严格分开：
*   - `pendingOfficeOpenFiles` → 通用 `WindowManager.openWindowApp('office')`
*   - `pendingWechatOpenFiles` → `handleWechatChatHistoryOpenFile`（仅 ZIP）
*   - `pendingOpenFolders` → 主窗 showOrCreate（独立窗暂不支持文件夹内容）
*/
function isZipPath(filePath) {
	return path.extname(filePath).toLowerCase() === ".zip";
}
/**
* open-file 路由器。持有三条互不干扰的 pending 队列。
* bootstrap 完成后 caller 调 `drainPending()` 一次性回放。
*/
var OpenFileRouter = class {
	deps;
	pendingOfficeOpenFiles = [];
	flushPendingOfficeOpenFilesPromise = null;
	pendingWechatOpenFiles = [];
	pendingOpenFolders = [];
	constructor(deps) {
		this.deps = deps;
	}
	/**
	* early-open-file-capture 入口：
	*   ZIP → 微信聊天记录；目录 → 主窗；其余 OS 白名单 → Office 独立窗。
	*/
	async handleFromMacosOpenFileEvent(filePath) {
		if (!filePath) return;
		this.deps.logger.info("[OpenFile] received", { filePath });
		const normalized = require_tencent_docs_prompt_selection.normalizeLocalDocumentFilePath(filePath) || filePath;
		let isDirectory = false;
		try {
			isDirectory = fs.statSync(normalized).isDirectory();
		} catch {}
		if (isDirectory) {
			this.enqueueOpenFolder(normalized);
			return;
		}
		if (isZipPath(normalized) && isWechatChatHistoryFile(normalized)) {
			await this.dispatchWechatOpenFile(normalized);
			return;
		}
		this.enqueueOfficeOsOpen(normalized, "mac-open-file");
	}
	/**
	* argv / second-instance 挑出的微信 ZIP 入口（caller 已判定 .zip）。
	*/
	handleWechatOnly(filePath) {
		this.dispatchWechatOpenFile(filePath).catch((err) => {
			this.deps.logger.error("[OpenFile] handleWechatOnly failed:", err);
		});
	}
	/**
	* OS 双击 / 打开方式：入队并打开（或追加到）Office 独立窗。
	* 兼容旧名 `enqueueTencentDocsLocalDocument` 的调用点。
	*/
	enqueueOfficeOsOpen(rawFilePath, source = "unknown") {
		const filePath = require_tencent_docs_prompt_selection.normalizeLocalDocumentFilePath(rawFilePath ?? "");
		if (!filePath) {
			this.deps.logger.warn("[OpenFile] ignored empty file path");
			return;
		}
		if (!isSupportedOfficeOsOpenFilePath(filePath)) {
			this.deps.logger.info("[OpenFile] ignored unsupported file type for office window", { filePath });
			return;
		}
		this.deps.logger.info("[OpenFile] enqueue office window open", {
			filePath,
			pendingCount: this.pendingOfficeOpenFiles.length + 1
		});
		this.pendingOfficeOpenFiles.push({
			filePath,
			source
		});
		this.flushPendingOfficeOpenFiles();
	}
	/** @deprecated 使用 enqueueOfficeOsOpen；保留别名避免调用点遗漏。 */
	enqueueTencentDocsLocalDocument(rawFilePath) {
		this.enqueueOfficeOsOpen(rawFilePath);
	}
	/** 文件夹右键「用 WorkBuddy 打开」：唤起主窗（独立窗暂不承载文件夹）。 */
	enqueueOpenFolder(rawFolderPath) {
		const folderPath = require_tencent_docs_prompt_selection.normalizeLocalDocumentFilePath(rawFolderPath ?? "");
		if (!folderPath) {
			this.deps.logger.warn("[OpenFile] ignored empty folder path");
			return;
		}
		try {
			if (!fs.statSync(folderPath).isDirectory()) {
				this.deps.logger.info("[OpenFile] ignored non-directory path for folder open", { folderPath });
				return;
			}
		} catch {
			this.deps.logger.info("[OpenFile] ignored unreadable folder path", { folderPath });
			return;
		}
		this.deps.logger.info("[OpenFile] enqueue folder open (main window)", { folderPath });
		this.pendingOpenFolders.push(folderPath);
		this.flushPendingOpenFolders();
	}
	/** bootstrap 完成时调：所有队列尝试 drain。幂等。 */
	drainPending() {
		this.flushPendingOfficeOpenFiles();
		this.drainPendingWechatOpenFiles();
		this.flushPendingOpenFolders();
	}
	async dispatchWechatOpenFile(filePath) {
		const windowManager = this.deps.getWindowManager();
		if (!windowManager) {
			this.pendingWechatOpenFiles.push(filePath);
			this.deps.logger.info("[OpenFile] queued to pendingWechatOpenFiles until WindowManager ready", { filePath });
			this.deps.logger.info("[WechatChatHistoryDelivery] open-file-route", {
				filePath,
				hasWindowManager: false,
				queued: true
			});
			return;
		}
		this.deps.logger.info("[WechatChatHistoryDelivery] open-file-route", {
			filePath,
			hasWindowManager: true,
			queued: false
		});
		await handleWechatChatHistoryOpenFile(filePath, {
			windowManager,
			tempDir: this.deps.getWechatChatHistoryTempDir(),
			logger: {
				info: (msg, payload) => this.deps.logger.info(msg, payload ?? {}),
				warn: (msg, payload) => this.deps.logger.warn(msg, payload ?? {}),
				error: (msg, error) => this.deps.logger.error(msg, error)
			},
			broadcastChip: this.deps.broadcastWechatChip
		});
	}
	flushPendingOfficeOpenFiles() {
		const windowManager = this.deps.getWindowManager();
		if (!windowManager || this.pendingOfficeOpenFiles.length === 0) return;
		if (this.flushPendingOfficeOpenFilesPromise) return;
		const pending = this.pendingOfficeOpenFiles;
		this.pendingOfficeOpenFiles = [];
		const filePaths = Array.from(new Set(pending.map((item) => item.filePath)));
		const sources = Array.from(new Set(pending.map((item) => item.source)));
		const source = sources.length === 1 ? sources[0] : "unknown";
		const flushPromise = Promise.resolve().then(() => {
			try {
				const remaining = [];
				const activeOfficeWindow = [...windowManager.registry.getByAppId("office")].sort((a, b) => (b.lastFocusedAt ?? b.openedAt) - (a.lastFocusedAt ?? a.openedAt))[0];
				for (const filePath of filePaths) {
					if (!focusOfficeFileWindow(windowManager, filePath)) {
						remaining.push(filePath);
						continue;
					}
					this.deps.logger.info("[OpenFile] focused existing office tab", {
						fileCount: 1,
						source
					});
				}
				if (remaining.length > 0) {
					const params = { resources: remaining.map((filePath) => ({
						type: "file",
						filePath
					})) };
					if (activeOfficeWindow) {
						windowManager.registeredWindows.enqueue(activeOfficeWindow.id, "open", params);
						windowManager.registeredWindows.focusWindow(activeOfficeWindow.id);
						this.deps.logger.info("[OpenFile] appended to active office window", {
							fileCount: remaining.length,
							source,
							windowId: activeOfficeWindow.id
						});
					} else {
						const result = windowManager.openWindowApp("office", params, "reuse-active");
						this.deps.logger.info("[OpenFile] opened office window", {
							fileCount: remaining.length,
							source,
							windowId: result.windowId
						});
					}
				}
			} catch (error) {
				this.deps.logger.warn("[OpenFile] Failed to open office window", {
					filePaths,
					error: error instanceof Error ? error.message : String(error)
				});
			}
		}).finally(() => {
			if (this.flushPendingOfficeOpenFilesPromise === flushPromise) this.flushPendingOfficeOpenFilesPromise = null;
			if (this.pendingOfficeOpenFiles.length > 0) this.flushPendingOfficeOpenFiles();
		});
		this.flushPendingOfficeOpenFilesPromise = flushPromise;
	}
	flushPendingOpenFolders() {
		const windowManager = this.deps.getWindowManager();
		if (!windowManager || this.pendingOpenFolders.length === 0) return;
		const folders = Array.from(new Set(this.pendingOpenFolders.splice(0)));
		this.deps.logger.info("[OpenFile] open folder via main window", { folders });
		windowManager.showOrCreate();
	}
	drainPendingWechatOpenFiles() {
		if (this.pendingWechatOpenFiles.length === 0) return;
		const files = this.pendingWechatOpenFiles.splice(0, this.pendingWechatOpenFiles.length);
		for (const file of files) this.dispatchWechatOpenFile(file).catch((err) => {
			this.deps.logger.error("[OpenFile] deferred wechat open failed:", err);
		});
	}
};
