/**
* 处理 bootstrap 失败。此函数不会 rethrow，所有异常都被兜住走用户可见流程。
*
* @param err 原始 bootstrap 抛出的错误
* @param deps 注入依赖
*/
async function handleBootstrapFailure(err, deps) {
	deps.log(`FATAL: bootstrap failed: ${err instanceof Error ? err.stack ?? err.message : String(err)}`);
	deps.errorLog("Failed to initialize:", err);
	deps.errorLog("Failed to initialize details:", node_util.default.inspect(err, {
		depth: 6,
		breakLength: 120
	}));
	deps.splash.forceClose();
	deps.rejectBootstrapDeferred?.(err instanceof Error ? err : new Error(String(err)));
	deps.runRepairScan(err);
	let fallbackWindowOk = false;
	if (deps.windowManager) try {
		ensureMainWindow(deps.windowManager);
		fallbackWindowOk = Boolean(deps.windowManager.getMainWindow());
		if (fallbackWindowOk) {
			deps.warnLog("Window created (fallback after bootstrap failure)");
			const errorMessage = err instanceof Error ? err.message : String(err);
			deps.windowManager.getMainWindow()?.webContents?.send("startup:message", {
				type: "startup:error",
				message: errorMessage,
				canRetry: true
			});
		}
	} catch (winErr) {
		deps.errorLog("Failed to create fallback window:", winErr);
	}
	if (fallbackWindowOk) deps.bootstrapQuitGuard.setStage("main-window-created", "fallback createWindow ok");
	else {
		deps.bootstrapQuitGuard.setStage("failed", "bootstrap and fallback both failed");
		deps.triggerUnavailableExit(deps.mainWindowFailedSource);
	}
}
