//#region src/main/integrations/win-share-target/registrar.ts
/**
* Windows Share Sheet sparse package self-heal registrar.
*
* Runs at main-process P3 (post-bootstrap) on Windows. Compensates the fact
* that the NSIS installer's `_RegisterWinShareTarget` PowerShell step can fail
* silently in some environments (timing / elevated-vs-user token split), which
* leaves `WorkBuddyShareTarget` unregistered even though the .msix and helper
* are correctly deployed under `$INSTDIR`. Symptom for end users: Share Sheet
* shows no WorkBuddy entry despite a successful install.
*
* Behaviour:
*   - Non-win32: no-op.
*   - `WorkBuddyShareTarget.msix` / helper missing under installDir (e.g. dev
*     build without win-share-target artifacts): no-op with an info log.
*   - Already registered (Get-AppxPackage returns the package): no-op.
*   - Otherwise: spawn `powershell.exe Add-AppxPackage -Path <msix> \
*     -ExternalLocation <installDir>`; log stdout/stderr + exit code.
*
* Non-fatal: any exception is logged and swallowed. This routine only enables
* the system Share Sheet entry; the app itself must continue to boot.
*/
/** Package identity name declared in `AppxManifest.xml` / `Identity/@Name`. */
var PACKAGE_NAME = "WorkBuddyShareTarget";
/** File name emitted by `build-win-share-target.mjs` and deployed at $INSTDIR. */
var MSIX_FILE = "WorkBuddyShareTarget.msix";
/** helper exe path under $INSTDIR (matches manifest Executable="share-target\WorkBuddyShareTarget.exe"). */
var HELPER_REL = path.join("share-target", "WorkBuddyShareTarget.exe");
/** Minimum Windows build that supports sparse packages / external location. */
var MIN_BUILD = 19041;
/** Windows PowerShell 5.1 lives here on every supported build (no PATH dependency). */
var POWERSHELL_PATH = process.env.SYSTEMROOT ? path.join(process.env.SYSTEMROOT, "System32", "WindowsPowerShell", "v1.0", "powershell.exe") : "powershell.exe";
/** Best-effort self-heal. Never throws. */
async function ensureWinShareTargetRegistered(options) {
	if (process.platform !== "win32") return;
	const { installDir, logDir, logger } = options;
	const msixPath = path.join(installDir, MSIX_FILE);
	const helperPath = path.join(installDir, HELPER_REL);
	if (!fs.existsSync(msixPath) || !fs.existsSync(helperPath)) {
		logger.info("[WinShareTarget] artifacts missing under installDir; skip self-heal", {
			installDir,
			msixExists: fs.existsSync(msixPath),
			helperExists: fs.existsSync(helperPath)
		});
		return;
	}
	if (!isWindowsBuildSupported()) {
		logger.info("[WinShareTarget] Windows build below MIN_BUILD; skip self-heal", { minBuild: MIN_BUILD });
		return;
	}
	const detailLogPath = path.join(logDir, "win-share-target-registrar.log");
	try {
		const existingFull = (await runPowerShellCapture(`$p = Get-AppxPackage -Name '${PACKAGE_NAME}' -ErrorAction SilentlyContinue; if ($p) { $p.PackageFullName } else { '' }`)).stdout.trim();
		if (existingFull) {
			logger.info("[WinShareTarget] already registered; skip self-heal", { packageFullName: existingFull });
			appendDetailLog(detailLogPath, `already registered: ${existingFull}`);
			return;
		}
		logger.info("[WinShareTarget] not registered; running self-heal Add-AppxPackage", {
			msix: msixPath,
			externalLocation: installDir
		});
		appendDetailLog(detailLogPath, `self-heal start msix="${msixPath}" external="${installDir}"`);
		const result = await runPowerShellCapture([
			"$ErrorActionPreference = 'Stop'",
			"try {",
			`  Add-AppxPackage -Path '${powerShellEscape(msixPath)}' -ExternalLocation '${powerShellEscape(installDir)}' -ErrorAction Stop`,
			`  $pkg = Get-AppxPackage -Name '${PACKAGE_NAME}' -ErrorAction SilentlyContinue`,
			"  if ($pkg) { Write-Output ('ok ' + $pkg.PackageFullName); exit 0 }",
			"  Write-Output 'verify_missing'; exit 3",
			"} catch {",
			"  $hres = try { '0x' + ('{0:X8}' -f $_.Exception.HResult) } catch { '' }",
			"  Write-Output ('err ' + $hres + ' ' + $_.Exception.Message)",
			"  exit 1",
			"}"
		].join("; "));
		appendDetailLog(detailLogPath, `self-heal exit=${result.exitCode} stdout=${result.stdout.trim()} stderr=${result.stderr.trim()}`);
		if (result.exitCode === 0) logger.info("[WinShareTarget] self-heal registered", { result: result.stdout.trim() });
		else logger.warn("[WinShareTarget] self-heal failed", {
			exitCode: result.exitCode,
			stdout: result.stdout.trim(),
			stderr: result.stderr.trim()
		});
	} catch (err) {
		logger.error("[WinShareTarget] self-heal threw unexpectedly:", err);
		try {
			appendDetailLog(detailLogPath, `self-heal threw: ${errorMessage(err)}`);
		} catch {}
	}
}
function isWindowsBuildSupported() {
	try {
		const parts = os.release().split(".");
		if (parts.length >= 3) {
			const build = Number(parts[2]);
			if (Number.isFinite(build) && build > 0) return build >= MIN_BUILD;
		}
	} catch {}
	return true;
}
function runPowerShellCapture(command) {
	return new Promise((resolve) => {
		const child = (0, child_process.spawn)(POWERSHELL_PATH, [
			"-NoLogo",
			"-NoProfile",
			"-NonInteractive",
			"-ExecutionPolicy",
			"Bypass",
			"-Command",
			"-"
		], { windowsHide: true });
		let stdout = "";
		let stderr = "";
		child.stdout.on("data", (chunk) => {
			stdout += chunk.toString("utf8");
		});
		child.stderr.on("data", (chunk) => {
			stderr += chunk.toString("utf8");
		});
		child.on("error", (err) => {
			resolve({
				exitCode: -1,
				stdout,
				stderr: `${stderr}\nspawn error: ${err.message}`
			});
		});
		child.on("close", (code) => {
			resolve({
				exitCode: code ?? -1,
				stdout,
				stderr
			});
		});
		child.stdin.end(command);
	});
}
/** Escape a value for embedding inside a single-quoted PowerShell string. */
function powerShellEscape(value) {
	return value.replace(/'/g, "''");
}
function appendDetailLog(logPath, line) {
	try {
		const parent = path.dirname(logPath);
		if (!fs.existsSync(parent)) fs.mkdirSync(parent, { recursive: true });
		fs.appendFileSync(logPath, `${(/* @__PURE__ */ new Date()).toISOString()} ${line}\n`, "utf8");
	} catch {}
}
function errorMessage(err) {
	if (err instanceof Error) return err.message;
	return String(err);
}
