//#region src/main/ipc/ipc-registry.ts
/** 一次性注册所有 pre-ready IPC。返回 disposer + windowManager 就绪回调。 */
function registerPreReadyIpc(options) {
	const debugHubEnabled = options.debugHubEnabled ?? (process.env.WORKBUDDY_IS_PACKAGED === "0" || process.env.WORKBUDDY_IS_PACKAGED === "false" || process.env.WORKBUDDY_ENABLE_DEBUG_HUB === "true");
	const disposers = [];
	disposers.push(registerCrashAndHostPlatformIpc({
		getCrashWriter: options.getCrashWriter,
		startupLog: options.startupLog
	}));
	disposers.push(registerMiscWindowIpc({
		getCrashWriter: options.getCrashWriter,
		debugHubEnabled
	}));
	disposers.push(registerWechatDetectIpc());
	disposers.push(registerResourceMonitorIpc({ ipcMain: options.ipcMain }));
	const rendererBootstrapResult = registerRendererBootstrapIpc({
		bootstrapDeferred: options.bootstrapDeferred,
		getWindowManager: options.getWindowManager,
		getStartupLifecycle: options.getStartupLifecycle,
		consumePendingOpenUrls: options.consumePendingOpenUrls,
		getOpenUrlRendererGeneration: options.getOpenUrlRendererGeneration,
		consumePendingWechatChips: options.consumePendingWechatChips,
		ackWechatChatHistoryChip: options.ackWechatChatHistoryChip,
		startupLog: options.startupLog
	});
	disposers.push(rendererBootstrapResult.dispose);
	disposers.push(registerAccountSnapshotIpc());
	disposers.push(registerTencentDocsIpc({
		getMainBootstrap: options.getMainBootstrap,
		ensureDebugCookies: options.ensureTencentDocsDebugCookies
	}));
	disposers.push(registerTencentDocsBridges({
		ipcMain: options.ipcMain,
		getMainBootstrap: options.getMainBootstrap,
		debugHubEnabled
	}));
	return {
		dispose: () => {
			for (const dispose of disposers.reverse()) try {
				dispose();
			} catch {}
		},
		notifyWindowManagerReady: rendererBootstrapResult.notifyWindowManagerReady
	};
}
/**
* 7 条腾讯文档 / desktop-host bridge 一次性注册，语义与 `registerTencentDocsIpc` 平级但
* 依赖 `ipcMain` 实例（而非 module-level ipcMain import）：
*
* - `webview-preload-bridge`  ：生产 `<webview>` preload 路径查询
* - `feature-list-bridge`     ：预览功能开关 + 在线预览 registry（getMainBootstrap 迟绑定）
* - `theme-bridge`            ：guest 页 cookie 主题透传
* - `language-bridge`         ：guest 页 cookie 多语言透传
* - `online-doc-login-cookie` ：全局订阅 preview webview did-finish-load
* - `local-file-drag`         ：default session 拖拽本地文件（非 ipcMain 但同批一次性副作用）
* - `debug-open-panel-ipc`    ：调试面板打开 handler（模块内 flag 幂等）
*
* 所有 7 条 handler 都是纯注册型（无 mainBootstrap 强依赖，只有 feature-list 用
* getMainBootstrap 迟绑定活实例），满足 pre-ready 判定标准。
*/
function registerTencentDocsBridges(deps) {
	registerTencentDocsWebviewPreloadBridge(deps.ipcMain);
	registerTencentDocsFeatureListBridge(deps.ipcMain, deps.getMainBootstrap);
	registerTencentDocsThemeBridge(deps.ipcMain);
	registerTencentDocsLanguageBridge(deps.ipcMain);
	installTencentDocsWebviewLoginCookieListener();
	registerLocalFileDragHandler();
	if (deps.debugHubEnabled) registerTencentDocsDebugOpenPanelIpc();
	return () => {};
}
