//#region src/main/system/gpu-degradation.ts
/**
* gpu-degradation — GPU 降级检测（黑屏/花屏/启动白屏防护，PRD §7 #18）
*
* 背景：GPU 进程异常是桌面应用黑屏/白屏的常见根因（旧显卡驱动、RDP/VNC/Citrix
* 远程桌面、无 GPU 直通虚拟机、Linux Wayland+Mesa）。对标 VSCode/Chrome：一旦上次
* 运行发生 GPU crash，则本次启动前禁用硬件加速，消除根因。
*
* 时序关键：`shouldDisableGpu` / `applyGpuDegradationIfNeeded` 必须在 `app.ready`
* 之前（Phase 1）调用——`app.disableHardwareAcceleration()` 只有在 ready 前才生效。
*
* 自动恢复：距上次 GPU crash 超过 24h 视为环境已恢复，不再降级（避免一次偶发 crash
* 永久禁用 GPU）。
*
* 设计约束：纯同步 fs + 异常静默降级，绝不因守卫自身出错阻断启动。
*/
/** 距上次 crash 超过此时长（24h）自动恢复硬件加速。 */
var RECOVER_WINDOW_MS = 864e5;
/** GPU crash 次数达到此阈值即降级（≥1 次，对标 VSCode/Chrome）。 */
var DEGRADE_THRESHOLD = 1;
var getDefaultPath = () => path.join(electron.app.getPath("userData"), "gpu-crash-info.json");
function readInfo(filePath) {
	try {
		return JSON.parse(fs.readFileSync(filePath, "utf-8"));
	} catch {
		return {};
	}
}
/** Phase 1 调用（app.ready 前）：判断本次启动是否需要禁用 GPU。 */
function shouldDisableGpu(filePath) {
	const info = readInfo(filePath ?? getDefaultPath());
	if (!info.lastGpuCrash) return false;
	if (Date.now() - info.lastGpuCrash > RECOVER_WINDOW_MS) return false;
	return (info.gpuCrashCount ?? 0) >= DEGRADE_THRESHOLD;
}
/** Phase 1 执行降级（必须在 app.ready 前）；返回是否已降级。 */
function applyGpuDegradationIfNeeded(filePath) {
	if (!shouldDisableGpu(filePath)) return false;
	electron.app.disableHardwareAcceleration();
	electron.app.commandLine.appendSwitch("disable-gpu");
	electron.app.commandLine.appendSwitch("disable-gpu-compositing");
	return true;
}
/** child-process-gone 中调用：记录一次 GPU crash（跨平台，供下次启动判断）。 */
function recordGpuCrash(reason, filePath) {
	const target = filePath ?? getDefaultPath();
	const info = readInfo(target);
	info.lastGpuCrash = Date.now();
	info.lastGpuCrashReason = reason;
	info.gpuCrashCount = (info.gpuCrashCount ?? 0) + 1;
	try {
		fs.writeFileSync(target, JSON.stringify(info));
	} catch {}
}
