//#region src/main/quit/signal-handlers.ts
/** Node 信号 → 标准退码（128 + signum）映射，保留 shell 语义。 */
var SIGNAL_EXIT_CODES = {
	SIGHUP: 129,
	SIGINT: 130,
	SIGTERM: 143,
	SIGBREAK: 149
};
/**
* 挂 4 类 handler：
*   1. `process.on('uncaughtException' / 'unhandledRejection')` （late）
*   2. `app.on('render-process-gone' / 'child-process-gone')`
*   3. `process.on(SIG*)`
*   4. `process.on('exit')`
*
* ⚠️ 只应调用一次；重复调用会重复注册 handler 导致 crash writer 双写。
*/
function attachProcessDiagnostics(deps) {
	process.on("uncaughtException", (error) => {
		deps.startupLog(`FATAL uncaughtException (late): ${error?.stack || error?.message || String(error)}`);
		if (error && (error.code === "EIO" || error.code === "EPIPE")) return;
		deps.logger.error("Uncaught exception:", error);
	});
	process.on("unhandledRejection", (reason, promise) => {
		deps.startupLog(`FATAL unhandledRejection (late): ${reason instanceof Error ? reason.stack || reason.message : String(reason)}`);
		deps.logger.error("Unhandled rejection at:", {
			promise,
			reason
		});
	});
	electron.app.on("render-process-gone", (_event, webContents, details) => {
		let url;
		let webContentsId;
		try {
			url = webContents.getURL();
			webContentsId = webContents.id;
		} catch {}
		const ctx = {
			reason: details.reason,
			exitCode: details.exitCode,
			url,
			webContentsId
		};
		deps.logger.error("[Crash] render-process-gone", ctx);
		deps.getCrashWriter()?.write({
			type: "renderer_crash",
			renderer: ctx
		});
	});
	electron.app.on("child-process-gone", (_event, details) => {
		const ctx = {
			processType: details.type,
			reason: details.reason,
			exitCode: details.exitCode,
			serviceName: details.serviceName,
			name: details.name
		};
		deps.logger.error("[Crash] child-process-gone", ctx);
		const crashType = details.type === "GPU" ? "gpu_crash" : "child_process_crash";
		deps.getCrashWriter()?.write({
			type: crashType,
			childProcess: ctx
		});
		if (details.type === "GPU" && details.reason !== "clean-exit" && process.platform === "win32") deps.getWindowManager()?.handleGpuCrash(details.reason, details.exitCode);
		if (details.type === "GPU" && details.reason !== "clean-exit") recordGpuCrash(details.reason);
	});
	for (const sig of Object.keys(SIGNAL_EXIT_CODES)) try {
		process.on(sig, () => {
			deps.startupLog(`Event: received signal ${sig}, exiting with code ${SIGNAL_EXIT_CODES[sig]}`);
			deps.logger.warn(`[Lifecycle] received signal ${sig}, exiting`);
			require_log_acl_guard.logLifecycleEvent("AppShutdown", {
				reason: "signal",
				signal: sig,
				exitCode: SIGNAL_EXIT_CODES[sig] ?? 1
			});
			try {
				require_log_acl_guard.getGlobalDatabaseRef()?.dispose();
			} catch {}
			process.exit(SIGNAL_EXIT_CODES[sig] ?? 1);
		});
	} catch {}
	process.on("exit", (code) => {
		require_log_acl_guard.logLifecycleEvent("AppShutdown", {
			reason: "process_exit",
			exitCode: code
		});
		deps.startupLog(`Event: process.exit code=${code} uptime=${Math.round(process.uptime())}s`);
		console.log(`[Lifecycle] process.exit fired code=${code} uptime=${Math.round(process.uptime())}s`);
	});
}
//#endregion
